def best_missing(gc, gbrk):
    # try all shifts of gbrk relative to gc, maximize overlap of nonzero cells
    R,C = len(gc), len(gc[0])
    best = None
    for dr in range(-len(gbrk), len(gc)):
        for dc in range(-len(gbrk[0]), len(gc[0])):
            ov = 0; miss = []
            for r in range(len(gbrk)):
                for c in range(len(gbrk[0])):
                    if gbrk[r][c]:
                        rr, cc = r+dr, c+dc
                        if 0<=rr<R and 0<=cc<C and gc[rr][cc]: ov += 1
            if best is None or ov > best[0]:
                best = (ov, dr, dc)
    ov, dr, dc = best
    R,C = len(gc), len(gc[0])
    m = [[0]*C for _ in range(R)]
    for r in range(len(gbrk)):
        for c in range(len(gbrk[0])):
            rr, cc = r+dr, c+dc
            if 0<=rr<R and 0<=cc<C and gc[rr][cc] and not gbrk[r][c]:
                m[rr][cc] = 1
    return best, m

